-- =============================================================================
--  UNIQO - 03_seed_config.sql : default site configuration + Design Lobby catalogue
--  GENERATED by db/mysql/uniqo_mysql.py seed - edit lobby_catalog.py, then regenerate.
--  Safe to re-run: existing rows are updated in place.
-- =============================================================================
USE uniqo;
SET NAMES utf8mb4;

ON DUPLICATE KEY UPDATE setting_value = new.setting_value, description = new.description;


ON DUPLICATE KEY UPDATE is_default = new.is_default, sort_order = new.sort_order;


ON DUPLICATE KEY UPDATE label = new.label, description = new.description, base_price = new.base_price, meters = new.meters, making_days = new.making_days, allows_belt = new.allows_belt, allows_dupatta = new.allows_dupatta, sort_order = new.sort_order;


ON DUPLICATE KEY UPDATE label = new.label, description = new.description, tag = new.tag, gsm = new.gsm, care = new.care, luxury = new.luxury, rate_per_meter = new.rate_per_meter, stat_comfort = new.stat_comfort, stat_drape = new.stat_drape, stat_stretch = new.stat_stretch, stat_breathability = new.stat_breathability, stat_formality = new.stat_formality, render_texture = new.render_texture, render_sheen = new.render_sheen, render_sheer = new.render_sheer, sort_order = new.sort_order;


DELETE FROM lobby_fabric_best_for;



ON DUPLICATE KEY UPDATE label = new.label, sort_order = new.sort_order;


ON DUPLICATE KEY UPDATE label = new.label, extra_meters = new.extra_meters, sort_order = new.sort_order;


ON DUPLICATE KEY UPDATE label = new.label, meter_factor = new.meter_factor, sort_order = new.sort_order;


ON DUPLICATE KEY UPDATE label = new.label, description = new.description, price = new.price, making_days = new.making_days, sort_order = new.sort_order;


ON DUPLICATE KEY UPDATE name = new.name, sort_order = new.sort_order;


ON DUPLICATE KEY UPDATE label = new.label, sort_order = new.sort_order;


ON DUPLICATE KEY UPDATE label = new.label, value = new.value, unit = new.unit;

