INSERT INTO site_settings (setting_key, setting_value, description) VALUES
  ('hero', '{"eyebrow": "Your Style. Your Rarity.", "title": "Wear a design only a handful will ever own.", "subtitle": "Uniqo is a showroom for clothes. Walk the floor, study every seam, make it yours, and claim a numbered piece from an edition that is strictly limited in your city."}', 'Home page hero: eyebrow, title, subtitle'),
  ('announcement', '"Every design is capped per city. When your city\'s edition sells out, it never returns."', 'Top announcement bar text (blank hides it)'),
  ('price_mode', '"reveal"', 'Default price display: visible | reveal | request'),
  ('sort_mode', '"manual"', 'Showroom order: manual | newest | price_asc | price_desc | scarcity | popular'),
  ('allow_customer_sort', 'true', 'Let customers re-sort the showroom'),
  ('show_sold_out', 'true', 'Keep sold-out designs visible'),
  ('locations', '["Hyderabad", "Bengaluru", "Mumbai", "Delhi", "Chennai"]', 'Cities served (mirrors the locations table)'),
  ('default_location', '"Hyderabad"', 'City shown to first-time visitors'),
  ('low_stock_threshold', '5', 'Show \'Only N left\' at or below this number'),
  ('currency', '"₹"', 'Currency symbol'),
  ('contact', '{"phone": "+91 00000 00000", "whatsapp": "", "email": "hello@uniqo.in", "instagram": "uniqo.studio", "address": "Uniqo Atelier, India"}', 'Phone, WhatsApp, email, Instagram, address'),
  ('lobby', '{"enabled": true, "show_estimate": true}', 'Design Lobby switches: enabled, show_estimate') AS new
