INSERT INTO lobby_silhouettes (silhouette_key, label, description, base_price, meters, making_days, allows_belt, allows_dupatta, sort_order) VALUES
  ('anarkali', 'Anarkali', 'A fitted yoke that blooms into a full, twirling flare.', 2500, 4.5, 10, 1, 1, 0),
  ('aline', 'A-line Gown', 'Fitted at the waist, gently flaring to the hem. Flatters everyone.', 1800, 3.0, 7, 1, 1, 1),
  ('sheath', 'Sheath Dress', 'A sculpted column that follows your line.', 2200, 2.2, 7, 1, 1, 2),
  ('kurta', 'Kurta Set', 'A straight kurta with side slits over tonal palazzos.', 1500, 4.0, 6, 1, 1, 3),
  ('lehenga', 'Lehenga', 'A cropped blouse with a sweeping, voluminous skirt.', 4500, 6.0, 20, 0, 1, 4),
  ('saree', 'Pre-draped Saree', 'Pleats and pallu stitched in place, on in under a minute.', 1200, 6.3, 9, 0, 0, 5) AS new
INSERT INTO lobby_fabrics (fabric_key, label, description, tag, gsm, care, luxury, rate_per_meter, stat_comfort, stat_drape, stat_stretch, stat_breathability, stat_formality, render_texture, render_sheen, render_sheer, sort_order) VALUES
  ('cotton', 'Cotton', 'Soft, breathable and honest. The fabric you forget you\'re wearing.', 'Everyday', '120-140', 'Machine wash cold', 1, 280, 5, 2, 1, 5, 2, 'weave', 0.1, 0, 0),
  ('linen', 'Linen', 'Crisp with a natural slub. Gets softer, and more yours, with every wear.', 'Breathable', '150-180', 'Hand wash, iron damp', 2, 650, 4, 2, 1, 5, 3, 'slub', 0.06, 0, 1),
  ('denim', 'Denim', 'Structured twill with attitude. Unexpected, and very hard to forget.', 'Street', '280-340', 'Wash inside out', 1, 420, 3, 1, 2, 3, 1, 'twill', 0.05, 0, 2),
  ('rayon', 'Rayon', 'Cool to touch with a liquid fall. Silk-like movement for every day.', 'Fluid', '110-130', 'Gentle hand wash', 1, 240, 5, 4, 2, 4, 2, 'flow', 0.2, 0, 3),
  ('crepe', 'Crepe', 'A fine pebbled surface that holds a clean, sculpted line.', 'Tailored', '150-180', 'Dry clean recommended', 2, 380, 4, 4, 3, 3, 4, 'pebble', 0.14, 0, 4),
  ('georgette', 'Georgette', 'Lightly crinkled and airy. Made for twirls and long evenings.', 'Flowy', '90-110', 'Dry clean recommended', 2, 350, 4, 5, 2, 4, 4, 'crinkle', 0.14, 0.18, 5),
  ('chiffon', 'Chiffon', 'Whisper-light and sheer. Floats behind you as you walk.', 'Sheer', '40-60', 'Dry clean only', 2, 320, 4, 5, 1, 5, 4, 'flow', 0.16, 0.34, 6),
  ('chanderi', 'Chanderi', 'Handwoven in Madhya Pradesh. A sheer silk-cotton with tiny woven gold buttis.', 'Handloom', '60-80', 'Dry clean only', 3, 900, 4, 3, 1, 5, 4, 'butti', 0.24, 0.26, 7),
  ('chikankari', 'Chikankari', 'Lucknow\'s white-on-fabric hand embroidery. Hundreds of tiny shadow stitches.', 'Handcrafted', '90-110', 'Gentle hand wash', 3, 1100, 5, 3, 1, 5, 3, 'chikan', 0.06, 0.1, 8),
  ('silk', 'Silk', 'Pure mulberry silk with a deep, living lustre. The fabric of heirlooms.', 'Heirloom', '80-100', 'Dry clean only', 3, 1800, 4, 4, 1, 3, 5, 'none', 0.42, 0, 9),
  ('satin_silk', 'Satin Silk', 'A mirror-smooth face that catches every light in the room.', 'Glossy', '90-120', 'Dry clean only', 2, 950, 3, 4, 1, 2, 5, 'none', 0.62, 0, 10),
  ('space_silk', 'Space Silk', 'Lightweight with a soft shimmer. Party-ready, without the weight.', 'Shimmer', '70-90', 'Gentle hand wash', 1, 520, 4, 4, 1, 3, 3, 'spark', 0.46, 0, 11) AS new
